begin;
create function private.normalize_crm_phone(value text) returns text language sql immutable set search_path='' as $$ select case when trim(value) like '+%' then '+'||regexp_replace(value,'[^0-9]','','g') when trim(value) like '00%' then '+'||substring(regexp_replace(value,'[^0-9]','','g') from 3) else regexp_replace(value,'[^0-9]','','g') end; $$;
create table public.lead_sources(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]{0,63}$'), active boolean not null default true, sort_order integer not null default 0 check(sort_order between 0 and 10000), unique(organization_id,key));
create table public.crm_pipeline_stages(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]{0,63}$'), active boolean not null default true, sort_order integer not null default 0 check(sort_order between 0 and 10000), unique(organization_id,key), outcome text not null default 'open' check(outcome in ('open','won','lost')), is_terminal boolean generated always as (outcome<>'open') stored);
create table public.crm_lost_reasons(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]{0,63}$'), active boolean not null default true, sort_order integer not null default 0 check(sort_order between 0 and 10000), unique(organization_id,key));
create table public.crm_requirement_fields(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]{0,63}$'), active boolean not null default true, sort_order integer not null default 0 check(sort_order between 0 and 10000), unique(organization_id,key), industry_id uuid references public.industries(id), field_type text not null check(field_type in ('text','number','select','boolean')), options jsonb not null default '[]' check(jsonb_typeof(options)='array' and jsonb_array_length(options)<=100), required boolean not null default false);
create table public.leads(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),lead_number text not null, name text not null check(length(trim(name)) between 1 and 200), company_name text not null default '' check(length(company_name)<=200), phone text not null check(length(phone) between 3 and 50), secondary_phone text not null default '' check(length(secondary_phone)<=50), phone_normalized text generated always as (private.normalize_crm_phone(phone)) stored, email text not null default '' check(length(email)<=254), email_normalized text generated always as(lower(trim(email))) stored, source_id uuid not null, source_detail text not null default '' check(length(source_detail)<=500), stage_id uuid not null, stage_entered_at timestamptz not null default now(), lifecycle text not null default 'open' check(lifecycle in ('open','won','lost','archived')), branch_id uuid, industry_id uuid references public.industries(id), service_type text not null default '' check(length(service_type)<=200), location text not null default '' check(length(location)<=500), site_address jsonb not null default '{"line1":"","line2":"","city":"","region":"","postal_code":"","country_code":""}' check(private.valid_address(site_address)), budget_min numeric(18,2) check(budget_min>=0), budget_max numeric(18,2) check(budget_max>=budget_min or budget_min is null), expected_start_date date, project_size text not null default '' check(length(project_size)<=200), assigned_to uuid, priority text not null default 'normal' check(priority in ('low','normal','high','urgent')), next_follow_up_at timestamptz, notes text not null default '' check(length(notes)<=10000), requirements jsonb not null default '{}' check(jsonb_typeof(requirements)='object' and octet_length(requirements::text)<=16000), lost_reason_id uuid, outcome_note text not null default '' check(length(outcome_note)<=3000), lost_at timestamptz, lost_by uuid references public.profiles(id), won_at timestamptz, won_by uuid references public.profiles(id), converted_customer_id uuid, converted_project_id uuid, converted_at timestamptz, converted_by uuid references public.profiles(id), unique(organization_id,lead_number),unique(organization_id,converted_project_id),check((converted_at is null and converted_customer_id is null and converted_project_id is null) or (converted_at is not null and converted_customer_id is not null and converted_project_id is not null)),foreign key(organization_id,source_id) references public.lead_sources(organization_id,id),foreign key(organization_id,stage_id) references public.crm_pipeline_stages(organization_id,id),foreign key(organization_id,branch_id) references public.branches(organization_id,id),foreign key(organization_id,lost_reason_id) references public.crm_lost_reasons(organization_id,id),foreign key(organization_id,converted_customer_id) references public.customers(organization_id,id),foreign key(organization_id,converted_customer_id,converted_project_id) references public.projects(organization_id,customer_id,id),foreign key(organization_id,assigned_to) references public.organization_memberships(organization_id,user_id));
create table public.lead_activities(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),lead_id uuid not null, activity_type text not null check(activity_type in ('note','phone_call','meeting','site_visit','follow_up','email_note','whatsapp_note','stage_change','assignment_change','quotation_created','quotation_issued','revision_created','quotation_shared','customer_viewed','customer_response','conversion','lost_reason','system')), subject text not null default '' check(length(subject)<=200), body text not null default '' check(length(body)<=10000), occurred_at timestamptz not null default now(), system_generated boolean not null default false, metadata jsonb not null default '{}' check(jsonb_typeof(metadata)='object' and octet_length(metadata::text)<=2000),foreign key(organization_id,lead_id) references public.leads(organization_id,id));
create table public.lead_followups(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),lead_id uuid not null, assigned_to uuid not null, due_at timestamptz not null, followup_type text not null check(followup_type in ('call','meeting','quotation','other')), note text not null default '' check(length(note)<=3000), status text not null default 'pending' check(status in ('pending','completed','cancelled')),completed_at timestamptz,completed_by uuid references public.profiles(id),outcome text not null default '' check(length(outcome)<=3000),foreign key(organization_id,lead_id) references public.leads(organization_id,id),foreign key(organization_id,assigned_to) references public.organization_memberships(organization_id,user_id));
create table public.site_visits(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),lead_id uuid not null,project_id uuid,scheduled_at timestamptz not null,assigned_to uuid not null,site_address jsonb not null check(private.valid_address(site_address)),contact_person text not null default '' check(length(contact_person)<=200),status text not null default 'scheduled' check(status in ('scheduled','completed','cancelled','rescheduled')),notes text not null default '' check(length(notes)<=10000),outcome text not null default '' check(length(outcome)<=10000),completed_at timestamptz,foreign key(organization_id,lead_id) references public.leads(organization_id,id),foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,assigned_to) references public.organization_memberships(organization_id,user_id));
create table public.quotation_share_links(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),revision_id uuid not null,expires_at timestamptz,revoked_at timestamptz,revoked_by uuid references public.profiles(id),pdf_enabled boolean not null default true,first_viewed_at timestamptz,last_viewed_at timestamptz,view_count bigint not null default 0 check(view_count>=0),foreign key(organization_id,revision_id) references public.quotation_revisions(organization_id,id));
create table public.quotation_customer_responses(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), created_by uuid references public.profiles(id) default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),quotation_id uuid not null,revision_id uuid not null unique,share_id uuid not null,action text not null check(action in ('approved','changes_requested','declined')),customer_name text not null check(length(trim(customer_name)) between 1 and 200),comment text not null default '' check(length(comment)<=3000),acknowledged boolean not null check(acknowledged),responded_at timestamptz not null default now(),accepted_amount text check(accepted_amount ~ '^(0|[1-9][0-9]*)(\.[0-9]+)?$'),currency text not null,snapshot_hash text not null,foreign key(organization_id,quotation_id,revision_id) references public.quotation_revisions(organization_id,quotation_id,id),foreign key(organization_id,share_id) references public.quotation_share_links(organization_id,id));
create table private.lead_number_sequences(organization_id uuid not null references public.organizations(id),year integer not null,prefix text not null default 'L' check(prefix ~ '^[A-Z][A-Z0-9-]{0,15}$'),last_number bigint not null default 0,primary key(organization_id,year));
create table private.quotation_share_secrets(share_id uuid primary key references public.quotation_share_links(id),token_hash text not null unique check(token_hash ~ '^[0-9a-f]{64}$'));
create table private.quotation_public_limits(share_id uuid not null references public.quotation_share_links(id),bucket timestamptz not null,operation text not null,hits integer not null,primary key(share_id,bucket,operation));
revoke all on private.lead_number_sequences,private.quotation_share_secrets,private.quotation_public_limits from public,anon,authenticated;
create index leads_stage on public.leads(organization_id,stage_id,stage_entered_at,id);
create index leads_assignee on public.leads(organization_id,assigned_to,updated_at desc,id);
create index leads_due on public.leads(organization_id,next_follow_up_at,id);
create index leads_source on public.leads(organization_id,source_id,created_at desc,id);
create index leads_phone on public.leads(organization_id,phone_normalized);
create index leads_email on public.leads(organization_id,email_normalized);
create index customers_crm_phone on public.customers(organization_id,private.normalize_crm_phone(phone));
create index customers_crm_email on public.customers(organization_id,lower(trim(email)));
create index lead_activity_time on public.lead_activities(organization_id,lead_id,occurred_at desc,id);
create index followup_queue on public.lead_followups(organization_id,assigned_to,status,due_at,id);
create index visits_queue on public.site_visits(organization_id,scheduled_at,id);
create index share_revision on public.quotation_share_links(organization_id,revision_id,created_at desc,id);
create index response_quote on public.quotation_customer_responses(organization_id,quotation_id,responded_at desc);
create function private.crm_access(org uuid,permission text) returns boolean language sql stable security definer set search_path='' as $$select private.has_permission(org,permission) and private.entitled(org,'crm');$$;
revoke all on function private.crm_access(uuid,text) from public,anon;grant execute on function private.crm_access(uuid,text) to authenticated;
alter table public.lead_sources enable row level security;alter table public.lead_sources force row level security;revoke all on public.lead_sources from public,anon,authenticated;grant select on public.lead_sources to authenticated;create policy tenant_read on public.lead_sources for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.lead_sources for each row execute function private.touch_updated_at();
alter table public.crm_pipeline_stages enable row level security;alter table public.crm_pipeline_stages force row level security;revoke all on public.crm_pipeline_stages from public,anon,authenticated;grant select on public.crm_pipeline_stages to authenticated;create policy tenant_read on public.crm_pipeline_stages for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.crm_pipeline_stages for each row execute function private.touch_updated_at();
alter table public.crm_lost_reasons enable row level security;alter table public.crm_lost_reasons force row level security;revoke all on public.crm_lost_reasons from public,anon,authenticated;grant select on public.crm_lost_reasons to authenticated;create policy tenant_read on public.crm_lost_reasons for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.crm_lost_reasons for each row execute function private.touch_updated_at();
alter table public.crm_requirement_fields enable row level security;alter table public.crm_requirement_fields force row level security;revoke all on public.crm_requirement_fields from public,anon,authenticated;grant select on public.crm_requirement_fields to authenticated;create policy tenant_read on public.crm_requirement_fields for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.crm_requirement_fields for each row execute function private.touch_updated_at();
alter table public.leads enable row level security;alter table public.leads force row level security;revoke all on public.leads from public,anon,authenticated;grant select on public.leads to authenticated;create policy tenant_read on public.leads for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.leads for each row execute function private.touch_updated_at();
alter table public.lead_activities enable row level security;alter table public.lead_activities force row level security;revoke all on public.lead_activities from public,anon,authenticated;grant select on public.lead_activities to authenticated;create policy tenant_read on public.lead_activities for select to authenticated using(private.crm_access(organization_id,'lead.view'));
alter table public.lead_followups enable row level security;alter table public.lead_followups force row level security;revoke all on public.lead_followups from public,anon,authenticated;grant select on public.lead_followups to authenticated;create policy tenant_read on public.lead_followups for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.lead_followups for each row execute function private.touch_updated_at();
alter table public.site_visits enable row level security;alter table public.site_visits force row level security;revoke all on public.site_visits from public,anon,authenticated;grant select on public.site_visits to authenticated;create policy tenant_read on public.site_visits for select to authenticated using(private.crm_access(organization_id,'lead.view'));
create trigger touch_updated_at before update on public.site_visits for each row execute function private.touch_updated_at();
alter table public.quotation_share_links enable row level security;alter table public.quotation_share_links force row level security;revoke all on public.quotation_share_links from public,anon,authenticated;grant select on public.quotation_share_links to authenticated;create policy tenant_read on public.quotation_share_links for select to authenticated using(private.commercial_access(organization_id,'quotation.share','quotation'));
create trigger touch_updated_at before update on public.quotation_share_links for each row execute function private.touch_updated_at();
alter table public.quotation_customer_responses enable row level security;alter table public.quotation_customer_responses force row level security;revoke all on public.quotation_customer_responses from public,anon,authenticated;grant select on public.quotation_customer_responses to authenticated;create policy tenant_read on public.quotation_customer_responses for select to authenticated using(private.commercial_access(organization_id,'quotation.customer_response.view','quotation'));
create function private.crm_append_only() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Append-only record' using errcode='23514';end$$;
create trigger append_only before update or delete on public.lead_activities for each row execute function private.crm_append_only();
create trigger append_only before update or delete on public.quotation_customer_responses for each row execute function private.crm_append_only();
revoke all on function private.crm_append_only(),private.normalize_crm_phone(text) from public,anon,authenticated;
insert into public.permissions(id,key,scope,description) select private.seed_uuid('business-os:'||k),k,'organization',replace(k,'.',' ') from unnest(array['lead.view','lead.create','lead.manage','lead.assign','lead.convert','lead.win','crm.activity.create','crm.followup.manage','crm.site_visit.manage','crm.pipeline.manage','crm.source.manage','quotation.share','quotation.customer_response.view']) k on conflict(key) do nothing;
insert into private.role_template_permissions(role_key,permission_key) select r.key,p.key from private.role_templates r cross join public.permissions p where p.key in ('lead.view','lead.create','lead.manage','lead.assign','lead.convert','lead.win','crm.activity.create','crm.followup.manage','crm.site_visit.manage','crm.pipeline.manage','crm.source.manage','quotation.share','quotation.customer_response.view') and (r.key in ('owner','admin') or (r.key in ('sales','branch_manager') and p.key not in ('lead.win','crm.pipeline.manage','crm.source.manage')) or (r.key='interior_designer' and p.key in ('lead.view','crm.activity.create','crm.site_visit.manage'))) on conflict do nothing;
insert into public.role_permissions(organization_id,role_id,permission_id) select r.organization_id,r.id,p.id from public.roles r join private.role_template_permissions t on t.role_key=r.key join public.permissions p on p.key=t.permission_key where p.key in ('lead.view','lead.create','lead.manage','lead.assign','lead.convert','lead.win','crm.activity.create','crm.followup.manage','crm.site_visit.manage','crm.pipeline.manage','crm.source.manage','quotation.share','quotation.customer_response.view') on conflict do nothing;
commit;
